function parseList(data,target,append=!1){if(NEXTPAGE||append)$(target+' res').append(tplList(data,$(target+' tpl').html()));else $(target+' res').html(tplList(data,$(target+' tpl').html()));$(target).addClass('_parsed');if(!append)NEXTPAGE=!1;imgUpdate()}
function parseData(data,target){$(target+' res').html(tplData(data,$(target+' tpl').html()));$(target).addClass('_parsed')}
function tplData(data,tpl){let res;let ptrn=/{([\w\.\[\]]+)}/;while((res=ptrn.exec(tpl))!=null){let level=res[1].split('.');if(eval('data.'+level[0])==null)eval('data.'+level[0]+'="-"');if(typeof eval('data.'+level[0])!='undefined')tpl=tpl.replace(res[0],eval('data.'+res[1]));else tpl=tpl.replace(res[0],'')}
return tpl}
function tplList(data,tpl){if(data){let html='';data.forEach(function(item){if(ROUTE.action=='history'){let history_item=item;let media=item.media;item=item.item;if(history_item.last_seen)item.last_seen_str=new Date(history_item.last_seen*1000).toLocaleString();if(history_item.time&&history_item.time>60)item.time_str=formatDuration(history_item.time);else if(history_item.time)item.time_str='~1 РјРёРЅ'
if(media&&media.snumber){item.snumber=media.snumber;item.number=media.number;item.media=media.id}}
if(item.title){let title=item.title.split(' / ');item.title_ru=title[0];item.title_en=title[1];if(item.type=='concert'){item.title_ru=item.title_en=item.title.replace('/','-')}}
if(item.imdb_rating)item.imdb_rating=parseFloat(item.imdb_rating).toFixed(1);if(item.kinopoisk_rating)item.kinopoisk_rating=parseFloat(item.kinopoisk_rating).toFixed(1);if(item.rating)item.rating=parseFloat(((item.rating_percentage)/10)).toFixed(1);item.countries_list='';item.countries_ids='';$.each(item.countries,function(key,val){item.countries_list+=' '+val.title+'';item.countries_ids+=' cid_'+val.id+''});if(item.director)item.directors_c=1;else item.directors_c=0;item.genres_list='';item.genres_ids='';$.each(item.genres,function(key,val){item.genres_list+=' '+val.title+'';item.genres_ids+=' gid_'+val.id+''});if(item.quality)item.quality_title=CONFIG.quality_list[item.quality];if(item.thumbnail)item.thumbnail=CDN(item.thumbnail);if(item.logos&&item.logos.s)item.logos.s=CDN(item.logos.s);if(item.posters&&item.posters.small)item.posters.small=CDN(item.posters.small);if(item.posters&&item.posters.medium)item.posters.medium=CDN(item.posters.medium);if(item.posters&&item.posters.big)item.posters.big=CDN(item.posters.big);html+=tplData(item,tpl)})
$body.removeClass('_next');return html}}
function message(text,type,timeout=5){if(type=='error')timeout=15;let id='t_'+new Date().getTime()+'_'+Math.random();$messages.append('<div class="msg '+type+'" data-id="'+id+'">'+text+'</div>');setTimeout(function(){$messages.find('.msg[data-id="'+id+'"]').addClass('show');setTimeout(function(){$messages.find('.msg[data-id="'+id+'"]').removeClass('show');setTimeout(function(){$messages.find('.msg[data-id="'+id+'"]').detach()},300)},timeout*1000)},100);return id}
$messages.on('click','.msg',function hide_opened(){$(this).removeClass('show')});function imgUpdate(){$('section.active res .item .poster').each(function(){let item=$(this);let imgUrl=item.attr('data-image');if(!item.hasClass('visible')&&imgUrl){let position=item.offset();let ypos=position.top;let scroll=$(window).scrollTop();let hwin=$(window).height();if((scroll+hwin)>ypos)item.css('background-image','url('+imgUrl+')').addClass('visible');}})}
function paginator(){let end=$('section.active .end');if(end.length>0){let position=end.offset();let ypos=position.top;let scroll=$(window).scrollTop();let hwin=$(window).height();if((scroll+hwin)>=ypos){if(!$body.hasClass('_next')&&ROUTE.action!='home'){if(PAGINATION[ROUTE.action]&&PAGINATION[ROUTE.action].current<PAGINATION[ROUTE.action].total){if(DEV)console.log('paginator');if(DEV)console.log(PAGINATION);PAGINATION[ROUTE.action].current+=1;NEXTPAGE=!0;router()}}}}}
function formatDuration(sec){let m=parseInt(sec/60%60);if(m==0)m='';else m+=' РјРёРЅ';let h=parseInt(sec/60/60);h=(h)?h+' С‡ ':'';return h+m}
function formatTime(sec){s=parseInt(sec%60).toString().padStart(2,'0');m=parseInt(sec/60%60).toString().padStart(2,'0')+':';h=parseInt(sec/60/60);h=(h)?h+':':'';return h+m+s}
