function placeholders(){$body.find('.placeholder').detach();$('input,select,textarea,label,.multiselect').each(function(){let placeholder=$(this).attr('placeholder');if($(this).val()!='')$(this).addClass('filled');else $(this).removeClass('filled');let position=$(this).position();if(placeholder)$(this).after('<i class="placeholder" style="left: '+(position.left)+'px; top: '+(position.top)+'px;   ">'+placeholder+'</i>');})}
$body.on('input.textchange change','input,select,textarea',function _input_change(){if($(this).val()!='')$(this).addClass('filled');else $(this).removeClass('filled')});function getAPIdata(url,callback,noCache=!1,apis=!1,method='get',fields={},processData=!0){if(NEXTPAGE)$body.addClass('_next');let splitter='?';if(url.indexOf('?')>0)splitter='&';let requestUrl=API+url+splitter+"access_token="+CONFIG.access_token;if(apis)requestUrl=APIS+url;let name=url2name(url);let expired=1;if(CACHE[name]){let expiredTime=3600;let cacheLivetime=parseInt(CACHE[name].time+expiredTime);let nowTime=parseInt(new Date().getTime()/1000);if(cacheLivetime>nowTime)expired=0}
if(!RELOAD&&!expired&&!noCache){$body.removeClass('_wait');callback(CACHE[name].data);paginator()}else{$body.addClass('_wait');RELOAD=!1;let headers={};if(!processData)headers={"content-type":"application/json"};inloading=$.ajax({url:requestUrl,type:method,cache:!1,data:fields,dataType:"json",processData:processData,headers:headers}).done(function(data){if(inloading.readyState==4)$body.removeClass('_wait');if(data&&data.pagination&&data.pagination.current==1)PAGINATION[ROUTE.action]=data.pagination;if(!noCache){CACHE[name]={};CACHE[name].time=parseInt(new Date().getTime()/1000);CACHE[name].data=data}
callback(data);paginator()}).fail(function(data){if(DEV)console.log(data);$body.removeClass('_wait');if(apis){message('РћС€РёР±РєР° API2','error')}else{if(data&&data.responseJSON&&data.responseJSON.error){message('РћС€РёР±РєР° API: '+data.responseJSON.error,'error');if(data.responseJSON.status=='401'&&url=='/user'){message('Р”Р»СЏ РїСЂРѕРґРѕР»Р¶РµРЅРёСЏ СЂР°Р±РѕС‚С‹ РЅРµРѕР±С…РѕРґРёРјР° Р°РєС‚РёРІР°С†РёСЏ СѓСЃС‚СЂРѕР№СЃС‚РІР°','error');getAccess()}else{}}else{if(data.status&&data.status!=0){message('РћС€РёР±РєР° API: '+data.status+' '+data.statusText,'error')}}}})}}
function url2name(url=document.location.href){return translit(url.toLowerCase()).replace(/[\W]/gi,'_')}
function get2array(url=window.location.href){let vars={},hash;let hashes=url.slice(url.indexOf('?')+1).split('&');for(let i=0;i<hashes.length;i++){hash=hashes[i].split('=');vars[hash[0]]=decodeURIComponent(hash[1])}
return vars}
function translit(text){let rus={"С‘":"yo","Р№":"i","С†":"ts","Сѓ":"u","Рє":"k","Рµ":"e","РЅ":"n","Рі":"g","С€":"sh","С‰":"sch","Р·":"z","С…":"h","СЉ":"'","С„":"f","С‹":"i","РІ":"v","Р°":"a","Рї":"p","СЂ":"r","Рѕ":"o","Р»":"l","Рґ":"d","Р¶":"zh","СЌ":"e","СЏ":"ya","С‡":"ch","СЃ":"s","Рј":"m","Рё":"i","С‚":"t","СЊ":"'","Р±":"b","СЋ":"yu"};return text.split('').map(function(char){return rus[char]||char}).join("")}
function letterSwitch(text){let lat={"q":"Р№","w":"С†","e":"Сѓ","r":"Рє","t":"Рµ","y":"РЅ","u":"Рі","i":"С€","o":"С‰","p":"Р·","[":"С…","]":"СЉ","a":"С„","s":"С‹","d":"РІ","f":"Р°","g":"Рї","h":"СЂ","j":"Рѕ","k":"Р»","l":"Рґ",";":"Р¶","'":"СЌ","z":"СЏ","x":"С‡","c":"СЃ","v":"Рј","b":"Рё","n":"С‚","m":"СЊ",",":"Р±",".":"СЋ","`":"С‘"};return text.split('').map(function(char){return lat[char]}).join("")}
function modalConfirm(msg,trueCallback){let $confirm=$body.find('#confirm');$confirm.find('.__cancel').off('click');$confirm.find('.__confirm').off('click');$confirm.find('h2').text(msg);$body.addClass('_mute');$confirm.addClass('_show');$confirm.find('.__cancel').on('click',function(){$body.removeClass('_mute');$confirm.removeClass('_show');return!1})
$confirm.find('.__confirm').on('click',function(){$body.removeClass('_mute');$confirm.removeClass('_show');trueCallback()})}
